"""Adaptive Cryptographic Security Policy Engine.

Analyzes file characterization (size, type, sensitivity) and contextual security
metrics (recent incidents, transfer frequency, session state) to determine optimal
cryptographic algorithms, key sizes, TTLs, rotation policies, and risk scores.
"""

from dataclasses import dataclass, asdict
from typing import List, Dict, Any


@dataclass
class AdaptivePolicyDecision:
    """The outcome generated by the Adaptive Security Policy Engine."""

    sensitivity: str
    cipher_algorithm: str
    key_size_bits: int
    ttl_seconds: int
    max_downloads: int
    rotation_threshold: int
    integrity_algorithm: str
    risk_score: int
    threat_level: str
    decision_reasons: List[str]

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class AdaptiveSecurityPolicyEngine:
    """Engine that determines cryptographic rules based on file and transfer context."""

    @staticmethod
    def evaluate(
        file_size_bytes: int,
        filename: str,
        sensitivity: str = "MEDIUM",
        recent_security_incidents: int = 0,
        preferred_cipher: str | None = None,
    ) -> AdaptivePolicyDecision:
        """Evaluate file characteristics and security context to decide policy."""
        sens = sensitivity.upper().strip()
        if sens not in ("LOW", "MEDIUM", "HIGH", "CRITICAL"):
            sens = "MEDIUM"

        reasons: List[str] = []

        # 1. Base sensitivity parameters
        if sens == "LOW":
            cipher = "AES-128-GCM"
            key_size = 128
            ttl_seconds = 86400  # 24 hours
            max_downloads = 10
            rotation_threshold = 5
            risk_score = 15
            threat_level = "LOW"
            reasons.append("Low sensitivity file: standard 128-bit key and 24-hour validity window.")

        elif sens == "MEDIUM":
            cipher = "AES-256-GCM"
            key_size = 256
            ttl_seconds = 14400  # 4 hours
            max_downloads = 5
            rotation_threshold = 2
            risk_score = 35
            threat_level = "NORMAL"
            reasons.append("Medium sensitivity file: 256-bit AES-GCM with 4-hour key expiration.")

        elif sens == "HIGH":
            cipher = "AES-256-GCM"
            key_size = 256
            ttl_seconds = 1800  # 30 minutes
            max_downloads = 2
            rotation_threshold = 1
            risk_score = 70
            threat_level = "ELEVATED"
            reasons.append("High sensitivity file: 256-bit AES-GCM with 30-minute key validity and quick rotation.")

        else:  # CRITICAL
            cipher = "AES-256-GCM"
            key_size = 256
            ttl_seconds = 600  # 10 minutes
            max_downloads = 1  # Single-use session key
            rotation_threshold = 1
            risk_score = 90
            threat_level = "CRITICAL"
            reasons.append("Critical sensitivity file: strict single-use session key with 10-minute expiry.")

        # 2. File size characterization
        if file_size_bytes > 50 * 1024 * 1024:  # > 50 MB
            # Give slightly more time to download large files
            ttl_seconds = max(ttl_seconds, 3600)
            reasons.append("Large file (>50MB): Adjusted minimum TTL to 1 hour to prevent mid-transfer expiration.")
        elif file_size_bytes < 1024:
            reasons.append("Small payload (<1KB): Highly suitable for rapid authenticated encryption.")

        # 3. Contextual security incidents adaptation
        if recent_security_incidents > 0:
            cipher = "AES-256-GCM"
            key_size = 256
            ttl_seconds = max(300, ttl_seconds // 2)  # Cut TTL in half, min 5 mins
            max_downloads = max(1, max_downloads // 2)
            risk_score = min(100, risk_score + 25)
            threat_level = "HIGH" if threat_level != "CRITICAL" else "CRITICAL"
            reasons.append(
                f"Incident Context: {recent_security_incidents} recent security event(s) detected. "
                "Enforced AES-256-GCM, reduced TTL by 50%, and restricted download limits."
            )

        # 4. Allow user override of cipher if specifically requested (e.g. for comparative benchmarking)
        if preferred_cipher:
            pref = preferred_cipher.upper()
            if "CHACHA" in pref:
                cipher = "CHACHA20-POLY1305"
                key_size = 256
                reasons.append("Cipher adapted to ChaCha20-Poly1305 based on configuration preference.")
            elif "128" in pref:
                cipher = "AES-128-GCM"
                key_size = 128
                reasons.append("Cipher adapted to AES-128-GCM based on configuration preference.")
            elif "256" in pref:
                cipher = "AES-256-GCM"
                key_size = 256
                reasons.append("Cipher set to AES-256-GCM based on configuration preference.")

        return AdaptivePolicyDecision(
            sensitivity=sens,
            cipher_algorithm=cipher,
            key_size_bits=key_size,
            ttl_seconds=ttl_seconds,
            max_downloads=max_downloads,
            rotation_threshold=rotation_threshold,
            integrity_algorithm="SHA-256",
            risk_score=risk_score,
            threat_level=threat_level,
            decision_reasons=reasons,
        )
